import Foundation
import RavanModel
import SwiftData

/// Imports the bundled offline dictionary (~21k entries, generated by tools/dictionary) on a
/// background context. Existing rows are never overwritten, so the user's edits survive
/// dictionary updates.
@ModelActor
public actor DictionarySeeder {
    /// Bump together with `version` in dictionary.json.
    public static let seedVersion = 2
    private static let defaultsKey = "ravan.seedVersion"
    private static let batchSize = 1_000

    public static var needsSeeding: Bool {
        UserDefaults.standard.integer(forKey: defaultsKey) < seedVersion
    }

    /// Returns the number of inserted words.
    @discardableResult
    public func seedIfNeeded() throws -> Int {
        guard Self.needsSeeding else { return 0 }
        guard let url = Bundle.module.url(forResource: "dictionary", withExtension: "json") else { return 0 }
        let dictionary = try JSONDecoder().decode(SeedDictionary.self, from: Data(contentsOf: url))

        var existing = Set<String>()
        var descriptor = FetchDescriptor<WordRecord>()
        descriptor.propertiesToFetch = [\.id]
        for record in try modelContext.fetch(descriptor) { existing.insert(record.id) }

        let now = Date.now
        var inserted = 0
        for (index, seed) in dictionary.words.enumerated() {
            let word = seed.word(now: now)
            guard !existing.contains(word.id) else { continue }
            modelContext.insert(WordRecord(word: word))
            inserted += 1
            if index % Self.batchSize == 0 { try modelContext.save() }
        }
        try modelContext.save()
        UserDefaults.standard.set(dictionary.version, forKey: Self.defaultsKey)
        return inserted
    }
}
